steps.code:
# Let's match the songs from old_songs (title + artist) to the songs in the playlists by comparing their titles and artists.
# We'll build a mapping from song_id to playlist_ids for removal, and collect the song_ids to add to the new playlist.

# Prepare a normalized set of (title, artist) from old_songs for matching
def normalize(s):
    return s.strip().lower()

old_songs_set = set()
for song in old_songs:
    title = normalize(song["title"])
    # Each artist in old_songs may be a comma-separated list
    for artist in [a.strip() for a in song["artist"].split(",")]:
        old_songs_set.add((title, normalize(artist)))

# Find song_ids in playlists that match old_songs
song_ids_to_archive = set()
song_id_to_playlist_ids = {}

for playlist in all_playlists:
    for song_id in playlist["song_ids"]:
        details = song_id_to_details[str(song_id)]
        song_title = normalize(details["title"])
        for artist in details["artists"]:
            artist_name = normalize(artist["name"])
            if (song_title, artist_name) in old_songs_set:
                song_ids_to_archive.add(song_id)
                song_id_to_playlist_ids.setdefault(song_id, []).append(playlist["playlist_id"])

print("song_ids_to_archive:", song_ids_to_archive)
print("song_id_to_playlist_ids:", song_id_to_playlist_ids)

