# The "Archived Songs" playlist has been created with playlist_id 654.
# Now, let's determine which old songs (by their Spotify song IDs) are present in any of Edwin's playlists.
# We'll collect all old song IDs that are present in any playlist, and for each playlist, which of these old songs are present.

old_song_ids = [entry["spotify_song_id"] for entry in json_friendly_mapping if entry["spotify_song_id"] is not None]

# For each playlist, find which old songs are present
playlist_old_songs = {}
for pid, song_ids in playlist_songs.items():
    playlist_old_songs[pid] = set(song_ids) & set(old_song_ids)

# Also, collect all old song IDs present in any playlist
old_song_ids_in_playlists = set()
for s in playlist_old_songs.values():
    old_song_ids_in_playlists.update(s)

print({
    "num_old_songs_found": len(old_song_ids_in_playlists),
    "old_song_ids_in_playlists": list(old_song_ids_in_playlists)
})

