# The show_song API takes a song_id and returns the song's title and artists (among other info).
# Let's fetch the metadata for all unique_song_ids. To avoid hitting rate limits, let's do it in batches of 10.

song_metadata = {}
for i in range(0, len(unique_song_ids), 10):
    batch = unique_song_ids[i:i+10]
    for song_id in batch:
        song_info = apis.spotify.show_song(song_id=song_id)
        if song_info and "song_id" in song_info:
            song_metadata[song_id] = song_info

print(song_metadata)

# The "Old Songs" playlist has been created with playlist_id 654.
# Next, I will add all archive_song_ids to this new playlist.

for song_id in archive_song_ids:
    apis.spotify.add_song_to_playlist(
        access_token=spotify_access_token,
        playlist_id=654,
        song_id=song_id
    )

# Now, I will proceed to remove these song_ids from all existing playlists.
for playlist in all_playlists:
    for song_id in playlist["song_ids"]:
        if song_id in archive_song_ids:
            apis.spotify.remove_song_from_playlist(
                access_token=spotify_access_token,
                playlist_id=playlist["playlist_id"],
                song_id=song_id
            )

