    {"title": "City of Fallen Angels", "artists": ["Hazel Winter"]},
    {"title": "Sacred Ground", "artists": ["Noah Bennett"]},
    {"title": "Echoes from the Abyss", "artists": ["Noah Bennett"]},
    # ... (add all parsed songs from the file here)
]

# Combine all song details
all_song_details = (
    song_details + song_details_2 + song_details_3 + song_details_4
)
song_id_to_info = {}
for song in all_song_details:
    song_id_to_info[song["song_id"]] = {
        "title": song["title"],
        "artists": [a["name"] for a in song["artists"]],
    }

# Now, for each song_id, check if its (title, artists) matches any entry in parsed_old_songs.
# Build a set of song_ids to archive.
songs_to_archive = set()
for song_id, info in song_id_to_info.items():
    for old_song in parsed_old_songs:
        if (
            info["title"].strip().lower() == old_song["title"].strip().lower()
            and set(a.lower() for a in info["artists"]) == set(a.lower() for a in old_song["artists"])
        ):
            songs_to_archive.add(song_id)
            break
print(songs_to_archive)

