steps.code:
# The extraction works. Now, let's repeat this process for all songs in the todo_songs list:
# For each song, search for it, get the first matching result, and extract the release month.
# We'll build a mapping from (title, artist) to release month.

release_months = {}

for song in todo_songs:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the first result that matches both title and artist (case-insensitive, partial match allowed for artist)
    found = None
    for result in results:
        if result["title"].lower() == song["title"].lower():
            for artist in result["artists"]:
                if artist["name"].lower() in song["artist"].lower() or song["artist"].lower() in artist["name"].lower():
                    found = result
                    break
            if found:
                break
    if found:
        release_date = found["release_date"]
        release_month = datetime.strptime(release_date, "%Y-%m-%dT%H:%M:%S").strftime("%m/%Y")
        release_months[(song["title"], song["artist"])] = release_month
    else:
        release_months[(song["title"], song["artist"])] = None

print(release_months)

# The error is because dictionary keys must be serializable types for printing, so let's convert the mapping to a list of dicts for display.
release_months_list = [
    {"title": title, "artist": artist, "release_month": release_month}
    for (title, artist), release_month in release_months.items()
]
print(release_months_list)

