steps.code:
# Great! Now let's automate this for all songs in the todo_songs list.
# We'll search for each song, extract the release month/year, and build a mapping from song title to release month.
release_months = {}

for song in todo_songs:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the result with the exact title and one of the artists matching
    found = None
    for result in results:
        if result["title"].lower() == song["title"].lower():
            artist_names = [a["name"].lower() for a in result["artists"]]
            # Check if any artist in the note matches any artist in the result
            note_artists = [a.strip().lower() for a in song["artist"].split(",")]
            if any(na in artist_names for na in note_artists):
                found = result
                break
    if found:
        release_date = found["release_date"]
        release_month = datetime.strptime(release_date, "%Y-%m-%dT%H:%M:%S").strftime("%m/%Y")
        release_months[song["title"]] = release_month
    else:
        release_months[song["title"]] = "UNKNOWN"

print(release_months)

